    11	}
    12	
    13	export interface MicRecorder {
    14		stop(): Promise<Blob>;
    15		cancel(): void;
    16	}
    17	
    18	/** Start recording from the default microphone. Throws if mic access fails. */
    19	export async function startMicRecording(): Promise<MicRecorder> {
    20		if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
    21			throw new Error("Microphone is not available in this browser.");
    22		}
    23		const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    24		const recorder = new MediaRecorder(stream);
    25		const chunks: BlobPart[] = [];
    26		recorder.addEventListener("dataavailable", (event) => {
    27			if (event.data && event.data.size > 0) chunks.push(event.data);
    28		});
    29		recorder.start();
    30	
    31		const stopTracks = () => stream.getTracks().forEach((track) => track.stop());
    32	
    33		return {
    34			stop: () =>
    35				new Promise<Blob>((resolve) => {
    36					recorder.addEventListener(
    37						"stop",
    38						() => {
    39							stopTracks();
    40							resolve(new Blob(chunks, { type: recorder.mimeType || "audio/webm" }));
    41						},
    42						{ once: true },
    43					);
    44					try {
    45						recorder.stop();
    46					} catch {
    47						stopTracks();
    48						resolve(new Blob(chunks, { type: "audio/webm" }));
    49					}
    50				}),
    51			cancel: () => {
    52				try {
    53					recorder.stop();
    54				} catch {
    55					// ignore
    56				}
    57				stopTracks();
    58			},
    59		};
    60	}
