    62	async function blobToBase64(blob: Blob): Promise<string> {
    63		const buffer = new Uint8Array(await blob.arrayBuffer());
    64		let binary = "";
    65		for (const byte of buffer) binary += String.fromCharCode(byte);
    66		return btoa(binary);
    67	}
